+            }
+            String[] parts = line.split(",", -1);
+            if (parts.length < 6) {
+                return;
+            }
+            Long ts = parseLong(parts[0]);
+            Long jobId = parseLong(parts[2]);
+            Integer eventType = parseInt(parts[5]);
+            if (ts == null || jobId == null || eventType == null) {
+                return;
+            }
+            out.collect(new TaskEvent(ts, jobId, eventType));
+        }
