+
+        @Override
+        public void open(Configuration parameters) {
+            ValueStateDescriptor<Long> desc = new ValueStateDescriptor<>("maxCount", Long.class);
+            maxCount = getRuntimeContext().getState(desc);
+        }
+
+        @Override
+        public void processElement(
+                Tuple2<Long, Long> value,
